resource "aws_autoscaling_group" "ecs" {
  name                = "${local.cluster_name}-asg"
  desired_capacity    = var.desired_capacity
  min_size            = var.min_capacity
  max_size            = var.max_capacity
  vpc_zone_identifier = aws_subnet.private[*].id

  launch_template {
    id      = aws_launch_template.ecs.id
    version = "$Latest"
  }

  dynamic "tag" {
    for_each = merge(local.common_tags, {
      Name             = "${local.cluster_name}-host"
      AmazonECSManaged = "true"
    })
    content {
      key                 = tag.key
      value               = tag.value
      propagate_at_launch = true
    }
  }

  # The ECS capacity provider has managed_scaling ENABLED, so it owns the
  # instance count. Without ignoring desired_capacity, every Terraform apply
  # resets it back to var.desired_capacity and terminates instances the capacity
  # provider launched — causing instance churn and ENI starvation.
  lifecycle {
    ignore_changes = [desired_capacity]
  }
}

