resource "aws_ecs_service" "adot" {
  name            = local.collector_name
  cluster         = var.ecs_cluster_id
  task_definition = aws_ecs_task_definition.adot.arn
  desired_count   = var.desired_count
  launch_type     = "EC2"

  # awsvpc tasks each consume one ENI. A t3.medium supports ~3 ENIs. The default
  # 200%/100% deployment launches new tasks before draining old ones, which can
  # exhaust available ENIs and stall the deployment with RESOURCE:ENI errors.
  # Capping at 100% with 50% minimum healthy drains one task before starting its
  # replacement, keeping peak ENI usage at steady state.
  deployment_maximum_percent         = 100
  deployment_minimum_healthy_percent = 50

  network_configuration {
    subnets         = var.subnet_ids
    security_groups = [aws_security_group.adot.id]
  }

  dynamic "load_balancer" {
    for_each = var.enable_nlb ? var.nlb_target_groups : []
    content {
      target_group_arn = load_balancer.value.arn
      container_name   = "adot-collector"
      container_port   = load_balancer.value.container_port
    }
  }

  dynamic "service_registries" {
    for_each = local.service_discovery_ns ? [1] : []
    content {
      registry_arn = aws_service_discovery_service.adot[0].arn
    }
  }

  tags = merge(local.common_tags, { Name = local.collector_name })
}

